QUESTION_BANK;

try {
    $questions = json_decode($bank, true, flags: JSON_THROW_ON_ERROR);
    Validator::make(['questions' => $questions], [
        'questions' => ['required', 'array', 'list', 'size:100'],
        'questions.*.prompt' => ['required', 'string', 'max:600', 'distinct:strict'],
        'questions.*.format' => ['required', Rule::in(['choice', 'reading'])],
        'questions.*.a' => ['required', 'string', 'max:300'],
        'questions.*.b' => ['required', 'string', 'max:300'],
        'questions.*.c' => ['required', 'string', 'max:300'],
        'questions.*.d' => ['required', 'string', 'max:300'],
        'questions.*.correct' => ['required', Rule::in(['a', 'b', 'c', 'd'])],
        'questions.*.points' => ['required', 'integer', 'in:1'],
        'questions.*.passage' => ['nullable', 'string', 'max:12000'],
    ], ['questions.*.prompt.distinct' => 'Each prompt must be unique across its part.'])->validate();
    $questions = AssessmentQuestions::validate($questions);
    $title = 'TOEIC-Style Reading Practice Exam (100 Questions)';
    $instructions = EditorHtml::clean(<<<'HTML'
        <p>Complete all 100 questions. Select one answer per question. Each correct answer is worth one point.</p>
        <ul>
        <li>Questions 1–30: Incomplete sentences.</li>
        <li>Questions 31–46: Text completion.</li>
        <li>Questions 47–100: Reading comprehension using workplace notices, correspondence, and related documents.</li>
        </ul>
        <p>Relevant texts appear with their questions. Scroll through all three parts and submit your answers at the bottom. This independently authored practice exam reports a practice percentage.</p>
        HTML, lesson: true);

    [$exam, $created] = DB::transaction(function () use ($title, $questions, $instructions): array {
        $type = ExamType::where('kind', 'exam')->where('name', 'English Proficiency Exam')->lockForUpdate()->first();
        if (!$type) {
            throw new RuntimeException('Create the English Proficiency Exam type before importing this exam.');
        }
        $existing = CourseExam::withTrashed()->where('kind', 'exam')->where('title', $title)->lockForUpdate()->get();
        if ($existing->isNotEmpty()) {
            $match = $existing->first();
            if ($existing->count() !== 1 || $match->trashed() || !$match->isSpecialized() || $match->questions != $questions) {
                throw new RuntimeException('The exam title is already in use. Review the existing exam before importing.');
            }

            return [$match, false];
        }

        return [CourseExam::create([
            'kind' => 'exam',
            'exam_type_id' => $type->id,
            'title' => $title,
            'viewer_mode' => 'specialized',
            'course_id' => null,
            'pricing' => null,
            'certificate_template_id' => null,
            'time_limit' => 180,
            'passing_percent' => 70,
            'attempt_limit' => 2,
            'public_requirement' => 'Read the workplace texts and select one answer per question. This original practice exam is scored out of 100.',
            'content_language' => 'English',
            'instructions_html' => $instructions,
            'questions' => $questions,
            'shuffle' => false,
            'gamified' => true,
            'live_feedback' => false,
            'published' => false,
        ]), true];
    });

    printf("DRAFT_IMPORT=%s\nVIEWER=%s\nQUESTIONS=%d\nSTATUS=%s\nEDIT_URL=%s\n",
        $created ? 'CREATED' : 'ALREADY_PRESENT',
        $exam->viewer_mode,
        count($exam->questions),
        $exam->managerStatus(),
        route('admin.exams.edit', ['exam' => $exam, 'lang' => 'en']));
} catch (Throwable $e) {
    $message = $e instanceof Illuminate\Validation\ValidationException
        ? implode(' ', $e->validator->errors()->all())
        : ($e::class === RuntimeException::class ? $e->getMessage() : 'Import aborted. Check the application logs.');
    fwrite(STDERR, $message.PHP_EOL);
    exit(1);
}
